// GitClear 2021-2024 数据（methodology caveats apply）：
// - refactor 占比：25% → <10%（4 年下降 60%）
// - code cloning metric：增加约 4x
// - code churn：增加约 2x
// AI 时代：快速凑出能跑的代码，但跳过重构 → 长期维护成本累积

// 2026 预测：AI 交互的累积成本
// 症状：
// - 上下文丢失：每次 restart 都要重新 context
// - 行为漂移：之前能做突然做不了
// - Prompt 考古：要挖历史才能理解现状
// Hunt 框架：tech debt → cognitive debt 主导

{
  "source": "GitClear annual code-quality research",
  "reports": [
    "Coding on Copilot (2024-01)",
    "AI Copilot Code Quality (2025-02)"
  ],
  "sampleSize": "more than 150m changed lines of code over 4 years",
  "shortTermChurn2024": "projected to double vs 2021 pre-AI baseline",
  "refactoringOrMovedLinesShare": { "2021": "25%", "2024": "less than 10%" },
  "copyPastedLinesShare": { "2021": "8.3%", "2024": "12.3%" }
}

// SonarQube official metric: duplicated_lines_density = duplicated_lines / lines * 100
function duplicatedLinesDensity(duplicatedLines, totalLines) {
  if (totalLines === 0) return 0;
  return (duplicatedLines / totalLines) * 100;
}

// Example: 1200 duplicated lines out of 10000 total lines
console.log(duplicatedLinesDensity(1200, 10000)); // => 12

